window.RP_SESSION={"id":"S-1b64060e107f","messages":[{"id":"RP-III-0130471","time":"2026-07-28T16:08:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 올리브는 고민을 하고 있습니다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130472","time":"2026-07-28T16:09:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그것은 바로 똥칸 냄새가 지독하다는 거지요.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130473","time":"2026-07-28T16:09:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 뒷간 청소를 하는 것에 불만은 없습니다. 올리브는 신입이잖아요. 까라면 까야죠.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130474","time":"2026-07-28T16:10:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그치만 누가 똥통 밖에 튀게 싸놓고 튄 것에는 불만이 있습니다. 누구야 대체.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130475","time":"2026-07-28T16:13:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"올리브는 똥통에서 오물을 퍼올려 나무동이에 담았습니다. 곧 텃밭의 비료가 될 녀석이죠.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130476","time":"2026-07-28T16:13:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"생각해보면요. 우리의 삶은 모두 똥으로 이루어진걸지도 모릅니다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130477","time":"2026-07-28T16:15:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"채소는 똥을 양분으로 삼아 키우고, 우린 그 채소와 그것을 먹은 고기를 양분으로 삼아 똥으로 만듭니다. 그리고 그것이 계속 반복되죠.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130478","time":"2026-07-28T16:15:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"어쩌면 우리의 몸은 모두 하나의 거대한 빨대일지도요.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130479","time":"2026-07-28T16:16:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그런 생각을 하다보니 어느새 나무동이에 오물이 가득 차올습니다. 올리브는 똥지게를 등에지고 뒷간을 나갑니다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130480","time":"2026-07-28T16:16:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"똥 같네요.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130481","time":"2026-07-28T16:16:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"똥!","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130482","time":"2026-07-28T16:18:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6ba6a097816f"]},{"id":"RP-III-0130483","time":"2026-07-28T16:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
